#!/usr/bin/env node
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';
import { readFile, writeFile, mkdir, glob } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { exec } from 'node:child_process';
import { promisify } from 'node:util';
import { dirname, join } from 'node:path';

const execAsync = promisify(exec);

// ── Constants ──────────────────────────────────────────────────────────────
const MOONSHOT_API_KEY = process.env.MOONSHOT_API_KEY;
const MOONSHOT_BASE = 'https://api.moonshot.ai/v1';
const MODEL = 'moonshot-v1-128k';
const MAX_RESULTS = 500;
const MAX_RESEARCH_CHARS = 400_000; // ~100K tokens

// ── Moonshot API helper ────────────────────────────────────────────────────
async function moonshotChat(messages, tools = null) {
  if (!MOONSHOT_API_KEY) {
    throw new Error('MOONSHOT_API_KEY environment variable is not set');
  }
  const body = { model: MODEL, messages };
  if (tools) body.tools = tools;

  const callApi = () => fetch(`${MOONSHOT_BASE}/chat/completions`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${MOONSHOT_API_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  let response = await callApi();

  if (response.status === 429) {
    await new Promise(r => setTimeout(r, 10_000));
    response = await callApi();
  }
  if (response.status === 401) throw new Error('MOONSHOT_API_KEY invalid or missing');
  if (!response.ok) throw new Error(`Moonshot API error ${response.status}: ${await response.text()}`);

  const data = await response.json();
  return data.choices[0].message;
}

// ── Strip HTML helper ──────────────────────────────────────────────────────
function stripHtml(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

// ── MCP server ─────────────────────────────────────────────────────────────
const server = new McpServer({ name: 'kimi-api-mcp', version: '1.0.0' });

// ──────────────────────────────────────────────────────────────────────────
// LOCAL TIER — no LLM, no cost
// ──────────────────────────────────────────────────────────────────────────

server.tool('kimi_read_file', 'Read a text file. Returns file content up to limit lines.', {
  path: z.string().describe('Absolute file path to read'),
  workFolder: z.string().optional(),
  offset: z.number().optional().describe('Line offset to start from (0-based)'),
  limit: z.number().optional().describe('Max lines to read (default: 1000)'),
}, async ({ path: filePath, offset = 0, limit = 1000 }) => {
  try {
    const content = await readFile(filePath, 'utf8');
    const lines = content.split('\n').slice(offset, offset + limit);
    const result = lines.map((l, i) => `${offset + i + 1}\t${l}`).join('\n');
    return { content: [{ type: 'text', text: result }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error reading file: ${err.message}` }] };
  }
});

server.tool('kimi_write_file', 'Create or overwrite a file with given content.', {
  path: z.string().describe('Absolute file path to write'),
  content: z.string().describe('Content to write'),
  workFolder: z.string().optional(),
}, async ({ path: filePath, content }) => {
  try {
    await mkdir(dirname(filePath), { recursive: true });
    await writeFile(filePath, content, 'utf8');
    return { content: [{ type: 'text', text: `Written: ${filePath}` }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error writing file: ${err.message}` }] };
  }
});

server.tool('kimi_edit_file', 'Find-and-replace edit in a file (exact string match).', {
  path: z.string().describe('Absolute file path to edit'),
  old_string: z.string().describe('Exact string to find'),
  new_string: z.string().describe('String to replace it with'),
  workFolder: z.string().optional(),
}, async ({ path: filePath, old_string, new_string }) => {
  try {
    const content = await readFile(filePath, 'utf8');
    if (!content.includes(old_string)) {
      return { content: [{ type: 'text', text: `Error: old_string not found in ${filePath}` }] };
    }
    await writeFile(filePath, content.replace(old_string, new_string), 'utf8');
    return { content: [{ type: 'text', text: `Edited: ${filePath}` }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error editing file: ${err.message}` }] };
  }
});

server.tool('kimi_glob', 'Find files matching a glob pattern.', {
  pattern: z.string().describe('Glob pattern (e.g. **/*.py)'),
  workFolder: z.string().optional().describe('Directory to search in'),
}, async ({ pattern, workFolder = process.cwd() }) => {
  try {
    const files = [];
    for await (const f of glob(pattern, { cwd: workFolder })) {
      files.push(f);
      if (files.length >= MAX_RESULTS) break;
    }
    return { content: [{ type: 'text', text: files.join('\n') || '(no matches)' }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error: ${err.message}` }] };
  }
});

server.tool('kimi_grep', 'Search for regex patterns in files.', {
  pattern: z.string().describe('Regex pattern to search for'),
  path: z.string().optional().describe('File or directory to search'),
  workFolder: z.string().optional(),
  glob: z.string().optional().describe('Glob filter (e.g. *.py)'),
}, async ({ pattern, path: searchPath = '.', workFolder = process.cwd(), glob: globFilter }) => {
  try {
    const globArg = globFilter ? `--glob '${globFilter}'` : '';
    const pat = pattern.replace(/'/g, "\\'");
    const tgt = searchPath.replace(/'/g, "\\'");
    const cmd = `rg -n --max-count 500 ${globArg} '${pat}' '${tgt}' 2>/dev/null || grep -rn --max-count=500 '${pat}' '${tgt}' 2>/dev/null`;
    const { stdout } = await execAsync(cmd, { cwd: workFolder, timeout: 30_000 });
    const lines = stdout.trim().split('\n').slice(0, MAX_RESULTS);
    return { content: [{ type: 'text', text: lines.join('\n') || '(no matches)' }] };
  } catch (err) {
    if (err.code === 1) return { content: [{ type: 'text', text: '(no matches)' }] };
    return { content: [{ type: 'text', text: `Error: ${err.message}` }] };
  }
});

server.tool('kimi_shell', 'Execute a shell command. Returns stdout, stderr, and exit code.', {
  command: z.string().describe('Shell command to execute'),
  workFolder: z.string().optional().describe('Working directory'),
  timeout: z.number().optional().describe('Timeout in seconds (default: 120)'),
}, async ({ command, workFolder = process.cwd(), timeout = 120 }) => {
  try {
    const { stdout, stderr } = await execAsync(command, {
      cwd: workFolder,
      timeout: timeout * 1000,
    });
    const out = [stdout, stderr].filter(Boolean).join('\n--- stderr ---\n');
    return { content: [{ type: 'text', text: out || '(no output)' }] };
  } catch (err) {
    const out = [err.stdout, err.stderr].filter(Boolean).join('\n');
    return { content: [{ type: 'text', text: `Exit ${err.code ?? 1}:\n${out}` }] };
  }
});

server.tool('kimi_fetch_url', 'Fetch a URL and return its text content (HTML stripped).', {
  url: z.string().describe('URL to fetch'),
  workFolder: z.string().optional(),
}, async ({ url }) => {
  try {
    const response = await fetch(url, {
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; kimi-api-mcp/1.0)' },
      signal: AbortSignal.timeout(30_000),
    });
    if (!response.ok) return { content: [{ type: 'text', text: `HTTP ${response.status}: ${response.statusText}` }] };
    const html = await response.text();
    return { content: [{ type: 'text', text: stripHtml(html).slice(0, 50_000) }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error fetching URL: ${err.message}` }] };
  }
});

// ──────────────────────────────────────────────────────────────────────────
// MOONSHOT API TIER
// ──────────────────────────────────────────────────────────────────────────

server.tool('kimi_think', 'Extended step-by-step reasoning for complex problems.', {
  problem: z.string().describe('Problem or question to reason about'),
  context: z.string().optional().describe('Additional context'),
  workFolder: z.string().optional(),
}, async ({ problem, context }) => {
  try {
    const userContent = context ? `Context:\n${context}\n\nProblem:\n${problem}` : problem;
    const msg = await moonshotChat([
      { role: 'system', content: 'You are a careful, methodical reasoner. Think step-by-step, consider edge cases, and arrive at a well-justified conclusion.' },
      { role: 'user', content: userContent },
    ]);
    return { content: [{ type: 'text', text: msg.content }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error: ${err.message}` }] };
  }
});

server.tool('kimi_review', 'Code review for bugs, security issues, and performance.', {
  path: z.string().describe('Absolute path to file to review'),
  focus: z.string().optional().describe('Specific aspect to focus on (e.g. security, performance)'),
  workFolder: z.string().optional(),
}, async ({ path: filePath, focus }) => {
  try {
    const code = await readFile(filePath, 'utf8');
    const focusNote = focus ? `Focus especially on: ${focus}.` : '';
    const msg = await moonshotChat([
      { role: 'system', content: `You are an expert code reviewer. Review for bugs, security issues, performance problems, and code quality. Be specific and actionable. ${focusNote}` },
      { role: 'user', content: `Review this file: ${filePath}\n\n\`\`\`\n${code}\n\`\`\`` },
    ]);
    return { content: [{ type: 'text', text: msg.content }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error: ${err.message}` }] };
  }
});

server.tool('kimi_test', 'Generate or improve tests for a source file.', {
  path: z.string().describe('Absolute path to source file to test'),
  framework: z.string().optional().describe('Test framework to use (e.g. pytest, vitest, jest)'),
  workFolder: z.string().optional(),
}, async ({ path: filePath, framework }) => {
  try {
    const code = await readFile(filePath, 'utf8');
    const fwNote = framework ? `Use the ${framework} framework.` : 'Use the most appropriate test framework for the language.';
    const msg = await moonshotChat([
      { role: 'system', content: `You are an expert at writing thorough, maintainable tests. Write tests that cover happy paths, edge cases, and error cases. ${fwNote}` },
      { role: 'user', content: `Write comprehensive tests for this file: ${filePath}\n\n\`\`\`\n${code}\n\`\`\`` },
    ]);
    return { content: [{ type: 'text', text: msg.content }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error: ${err.message}` }] };
  }
});

server.tool('kimi_research', 'Analyze a codebase or answer questions using 128K context.', {
  question: z.string().describe('Question to answer or topic to research'),
  context: z.string().optional().describe('Additional context or constraints'),
  workFolder: z.string().optional().describe('Directory to read files from'),
}, async ({ question, context, workFolder }) => {
  try {
    let filesContext = '';
    if (workFolder && existsSync(workFolder)) {
      const files = [];
      for await (const f of glob('**/*.{js,ts,py,mjs,cjs,json,md,txt,yaml,yml}', { cwd: workFolder })) {
        files.push(f);
        if (files.length >= 50) break;
      }
      let totalChars = 0;
      const parts = [];
      for (const f of files) {
        try {
          const content = await readFile(join(workFolder, f), 'utf8');
          if (totalChars + content.length > MAX_RESEARCH_CHARS) {
            parts.push(`[${f}: truncated — context limit reached]`);
            break;
          }
          parts.push(`=== ${f} ===\n${content}`);
          totalChars += content.length;
        } catch { /* skip unreadable files */ }
      }
      filesContext = parts.join('\n\n');
    }

    const userContent = [
      context ? `Context: ${context}` : '',
      filesContext ? `Codebase files:\n${filesContext}` : '',
      `Question: ${question}`,
    ].filter(Boolean).join('\n\n');

    const msg = await moonshotChat([
      { role: 'system', content: 'You are a senior software architect. Analyze the provided code and answer questions accurately and concisely.' },
      { role: 'user', content: userContent },
    ]);
    return { content: [{ type: 'text', text: msg.content }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error: ${err.message}` }] };
  }
});

server.tool('kimi_read_media', 'Analyze images using Moonshot vision API.', {
  path: z.string().describe('Absolute path to image file'),
  prompt: z.string().optional().describe('What to analyze (default: describe the image)'),
  workFolder: z.string().optional(),
}, async ({ path: filePath, prompt: userPrompt = 'Describe this image in detail.' }) => {
  try {
    const data = await readFile(filePath);
    const ext = filePath.split('.').pop().toLowerCase();
    const mimeMap = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif', webp: 'image/webp' };
    const mime = mimeMap[ext] || 'image/jpeg';
    const b64 = data.toString('base64');
    const msg = await moonshotChat([{
      role: 'user',
      content: [
        { type: 'image_url', image_url: { url: `data:${mime};base64,${b64}` } },
        { type: 'text', text: userPrompt },
      ],
    }]);
    return { content: [{ type: 'text', text: msg.content }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error: ${err.message}` }] };
  }
});

server.tool('kimi_web_search', 'Search the web and return AI-summarized results.', {
  query: z.string().describe('Search query'),
  max_results: z.number().optional().describe('Max results to fetch (default: 10)'),
  workFolder: z.string().optional(),
}, async ({ query, max_results = 10 }) => {
  try {
    const params = new URLSearchParams({ q: query, kl: 'us-en' });
    const response = await fetch('https://lite.duckduckgo.com/lite/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'User-Agent': 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)',
      },
      body: params.toString(),
      signal: AbortSignal.timeout(15_000),
    });
    const html = await response.text();
    const linkRe = /<a[^>]+class="result-link"[^>]*>([^<]+)<\/a>/gi;
    const snippetRe = /<td[^>]+class="result-snippet"[^>]*>([\s\S]*?)<\/td>/gi;
    const links = [...html.matchAll(linkRe)].map(m => m[1].trim());
    const snips = [...html.matchAll(snippetRe)].map(m => stripHtml(m[1]).trim());
    const snippets = links.slice(0, max_results)
      .map((l, i) => `${i + 1}. ${l}\n   ${snips[i] || ''}`)
      .join('\n\n');
    const rawResults = snippets || html.slice(0, 3000);
    const msg = await moonshotChat([
      { role: 'system', content: 'You summarize web search results concisely and accurately.' },
      { role: 'user', content: `Search query: "${query}"\n\nResults:\n${rawResults}\n\nProvide a clear summary of the key findings.` },
    ]);
    return { content: [{ type: 'text', text: msg.content }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Error: ${err.message}` }] };
  }
});

// ── kimi_agent — agentic loop ──────────────────────────────────────────────

const AGENT_TOOLS = [
  { type: 'function', function: { name: 'read_file', description: 'Read a file from disk', parameters: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } } },
  { type: 'function', function: { name: 'shell', description: 'Execute a shell command', parameters: { type: 'object', properties: { command: { type: 'string' }, cwd: { type: 'string' } }, required: ['command'] } } },
  { type: 'function', function: { name: 'glob_files', description: 'Find files matching a glob pattern', parameters: { type: 'object', properties: { pattern: { type: 'string' }, cwd: { type: 'string' } }, required: ['pattern'] } } },
  { type: 'function', function: { name: 'grep_files', description: 'Search for a pattern in files', parameters: { type: 'object', properties: { pattern: { type: 'string' }, path: { type: 'string' } }, required: ['pattern'] } } },
  { type: 'function', function: { name: 'fetch_url', description: 'Fetch content from a URL', parameters: { type: 'object', properties: { url: { type: 'string' } }, required: ['url'] } } },
  { type: 'function', function: { name: 'write_file', description: 'Write content to a file', parameters: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'] } } },
];

async function executeAgentTool(name, args, workFolder) {
  switch (name) {
    case 'read_file': try { return await readFile(args.path, 'utf8'); } catch (e) { return `Error: ${e.message}`; }
    case 'shell': {
      try { const { stdout, stderr } = await execAsync(args.command, { cwd: args.cwd || workFolder, timeout: 120_000 }); return [stdout, stderr].filter(Boolean).join('\n') || '(no output)'; }
      catch (e) { return `Exit ${e.code}: ${e.stdout || ''}\n${e.stderr || ''}`; }
    }
    case 'glob_files': {
      const files = [];
      try { for await (const f of glob(args.pattern, { cwd: args.cwd || workFolder })) { files.push(f); if (files.length >= MAX_RESULTS) break; } }
      catch (e) { return `Error: ${e.message}`; }
      return files.join('\n') || '(no matches)';
    }
    case 'grep_files': {
      try { const { stdout } = await execAsync(`rg -n '${args.pattern.replace(/'/g, "\\'")}' '${args.path || '.'}'`, { cwd: workFolder, timeout: 30_000 }); return stdout.trim() || '(no matches)'; }
      catch { return '(no matches)'; }
    }
    case 'fetch_url': {
      try { const r = await fetch(args.url, { signal: AbortSignal.timeout(30_000) }); return stripHtml(await r.text()).slice(0, 20_000); }
      catch (e) { return `Error: ${e.message}`; }
    }
    case 'write_file': {
      try { await mkdir(dirname(args.path), { recursive: true }); await writeFile(args.path, args.content, 'utf8'); return `Written: ${args.path}`; }
      catch (e) { return `Error: ${e.message}`; }
    }
    default: return `Unknown tool: ${name}`;
  }
}

server.tool('kimi_agent', 'Autonomous agent for complex multi-step tasks using Kimi K2.5.', {
  prompt: z.string().describe('Task description for the agent'),
  workFolder: z.string().optional().describe('Working directory'),
  timeout: z.number().optional().describe('Timeout in seconds (default: 300)'),
}, async ({ prompt, workFolder = process.cwd(), timeout = 300 }) => {
  const startTime = Date.now();
  const messages = [
    { role: 'system', content: `You are an autonomous coding agent. Use the available tools to complete the task. Work in: ${workFolder}` },
    { role: 'user', content: prompt },
  ];
  let iterations = 0;
  try {
    while (iterations < 15) {
      if (Date.now() - startTime > timeout * 1000) {
        return { content: [{ type: 'text', text: `[Timeout after ${iterations} iterations]\n\n${messages.at(-1)?.content || ''}` }] };
      }
      const msg = await moonshotChat(messages, AGENT_TOOLS);
      messages.push(msg);
      if (!msg.tool_calls || msg.tool_calls.length === 0) {
        return { content: [{ type: 'text', text: msg.content || '(no response)' }] };
      }
      for (const tc of msg.tool_calls) {
        const args = JSON.parse(tc.function.arguments || '{}');
        const result = await executeAgentTool(tc.function.name, args, workFolder);
        messages.push({ role: 'tool', tool_call_id: tc.id, content: String(result) });
      }
      iterations++;
    }
    return { content: [{ type: 'text', text: `[Max iterations (15) reached]\n\n${messages.at(-1)?.content || ''}` }] };
  } catch (err) {
    return { content: [{ type: 'text', text: `Agent error: ${err.message}` }] };
  }
});

// ── Start ──────────────────────────────────────────────────────────────────
const transport = new StdioServerTransport();
await server.connect(transport);
